function handleEngineEvents(event, data) {
    if (event === "loaded") {
        currentApp = data;
        terminal.output(`<br />Executing source code...<br /><br />`);
        terminal.idle();
    }
    else if (event === "started") {
        currentApp = data;
        console.info(`Execution started ${appId}`);
        runButton.style.display = "none";
        endButton.style.display = "inline";
        breakButton.style.display = "inline";
    }
    else if (event === "debug") {
        logToTerminal(data);
        scrollToBottom();
    }
    else if (event === "closed" || event === "error") {
        currentApp = data;
        console.info(`Execution terminated! ${event}: ${data}`);
        terminal.idle();
        runButton.style.display = "inline";
        endButton.style.display = "none";
        resumeButton.style.display = "none";
        breakButton.style.display = "none";
    }
}
function logToTerminal(data) {
    if (data?.level === "stop") {
        terminal.output("<br />");
        terminal.setPrompt();
        resumeButton.style.display = "inline";
        breakButton.style.display = "none";
    }
    else if (data?.level === "continue") {
        terminal.idle();
        resumeButton.style.display = "none";
        breakButton.style.display = "inline";
    }
    else if (typeof data?.content === "string") {
        updateTerminal(data.content, data.level);
    }
}
function updateTerminal(text, level = "print") {
    let output = text.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
    if (level === "print" || level === "debug") {
        const promptLen = `${prompt}&gt; `.length;
        if (output.endsWith(`${prompt}&gt; `)) {
            output = output.slice(0, output.length - promptLen);
        }
    }
    output = output.replaceAll(" ", "&nbsp;");
    const lines = output.trim().split(/\r?\n/);
    for (const rawLine of lines) {
        let line = rawLine || "&zwnj;";
        if (colorizeConsoleLogs) {
            if (level === "print" || level === "beacon") {
                line = terminal.highlight(line);
            }
            else if (level === "debug") {
                line = `<span style="color: ${COLOR_THEMES[activeTheme].debug}">${terminal.highlight(line)}</span>`;
            }
            else if (level === "warning") {
                line = terminal.colorize(line, COLOR_THEMES[activeTheme].warning);
            }
            else if (level === "error") {
                line = terminal.colorize(line, COLOR_THEMES[activeTheme].error);
            }
        }
        terminal.outputHTML(line);
        terminal.resetCommand();
    }
}
function scrollToBottom() {
    if (consoleLogsContainer.children.length) {
        const terminal = consoleLogsContainer.children[0];
        const scrollHeight = terminal.scrollHeight;
        terminal.scrollTo({
            top: scrollHeight,
            left: 0,
            behavior: "auto",
        });
    }
}
